using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using OneLobby.Replication;
using Xunit;
using Xunit.Abstractions;

namespace OneLobby.Replication.Tests
{
    /// <summary>
    /// Every case of spec/vectors/net-player.json (generated by the JS client, never edited here), both directions: the encoder
    /// must give the file's bytes, the decoder must give the file's values within 1e-5, and every invalid case must fail with
    /// its error name.
    /// </summary>
    public class NetPlayerVectorTests
    {
        private readonly ITestOutputHelper _out;
        public NetPlayerVectorTests(ITestOutputHelper output) { _out = output; }

        internal static JsonElement Load()
        {
            var dir = AppContext.BaseDirectory;
            while (dir != null && !File.Exists(Path.Combine(dir, "spec", "vectors", "net-player.json"))) dir = Path.GetDirectoryName(dir);
            return JsonDocument.Parse(File.ReadAllText(Path.Combine(dir!, "spec", "vectors", "net-player.json"))).RootElement;
        }

        private static string Hex(ReadOnlySpan<byte> b) => Convert.ToHexString(b).ToLowerInvariant();

        private static PlayerCodec CodecOf(JsonElement root, string name)
        {
            var c = root.GetProperty("configs").GetProperty(name);
            var omit = c.GetProperty("omit").EnumerateArray().Select(e => e.GetString()!).ToList();
            return new PlayerCodec(new PlayerWireConfig(c.GetProperty("space").GetString()!, c.GetProperty("range").GetDouble(), c.GetProperty("velocityRange").GetDouble(), omit));
        }

        private static double N(JsonElement e, string k) => e.TryGetProperty(k, out var v) ? v.GetDouble() : 0;
        private static bool B(JsonElement e, string k) => e.GetProperty(k).GetBoolean();

        private static PlayerState StateOf(JsonElement e) => new PlayerState
        {
            X = N(e, "x"), Y = N(e, "y"), Z = N(e, "z"), Vx = N(e, "vx"), Vy = N(e, "vy"), Vz = N(e, "vz"), Yaw = N(e, "yaw"), Pitch = N(e, "pitch"),
            OnGround = B(e, "onGround"), Mode = (int)N(e, "mode"), Item = (int)N(e, "item"), Aiming = B(e, "aiming"), Blocking = B(e, "blocking"),
            Health = (int)N(e, "health"), Alive = B(e, "alive"), Team = (int)N(e, "team"), Teleport = (int)N(e, "teleport"),
        };

        private static void AssertState(PlayerState want, PlayerState got, string what)
        {
            Assert.True(Math.Abs(want.X - got.X) < 1e-5 && Math.Abs(want.Y - got.Y) < 1e-5 && Math.Abs(want.Z - got.Z) < 1e-5, what + " position");
            Assert.True(Math.Abs(want.Vx - got.Vx) < 1e-5 && Math.Abs(want.Vy - got.Vy) < 1e-5 && Math.Abs(want.Vz - got.Vz) < 1e-5, what + " velocity");
            Assert.True(Math.Abs(want.Yaw - got.Yaw) < 1e-5 && Math.Abs(want.Pitch - got.Pitch) < 1e-5, what + " angles");
            Assert.True(want.OnGround == got.OnGround && want.Mode == got.Mode && want.Item == got.Item && want.Aiming == got.Aiming && want.Blocking == got.Blocking
                && want.Health == got.Health && want.Alive == got.Alive && want.Team == got.Team && want.Teleport == got.Teleport, what + " flags");
        }

        private static NetPlayerInput InputOf(JsonElement e)
        {
            var b = PlayerButtons.None;
            var names = new[] { "jump", "crouch", "sprint", "aim", "block", "fire", "use", "reload" };
            for (var i = 0; i < 8; i++) if (B(e.GetProperty("buttons"), names[i])) b |= (PlayerButtons)(1 << i);
            return new NetPlayerInput { MoveX = N(e, "moveX"), MoveY = N(e, "moveY"), Yaw = N(e, "yaw"), Pitch = N(e, "pitch"), Buttons = b };
        }

        private static ActionArgs ArgsOf(JsonElement e) => new ActionArgs
        {
            Impact = N(e, "impact"), Yaw = N(e, "yaw"), Pitch = N(e, "pitch"), View = (uint)N(e, "view"), Swing = (int)N(e, "swing"), Target = (int)N(e, "target"),
            Slot = (int)N(e, "slot"), Power = N(e, "power"), By = (int)N(e, "by"), Damage = (int)N(e, "damage"), Emote = (int)N(e, "emote"),
        };

        private static PlayerAction Action(string name) { Assert.True(PlayerWire.TryParseAction(name, out var a), name); return a; }

        [Fact]
        public void PositionBitsMatch()
        {
            var n = 0;
            foreach (var p in Load().GetProperty("positionBits").EnumerateArray()) { Assert.Equal(p.GetProperty("bits").GetInt32(), PlayerWire.PositionBits(p.GetProperty("range").GetDouble())); n++; }
            Assert.Equal(8, n);
        }

        [Fact]
        public void StatesEncodeAndDecodeBothWays()
        {
            var root = Load();
            var n = 0;
            foreach (var v in root.GetProperty("states").EnumerateArray())
            {
                var name = v.GetProperty("name").GetString()!;
                var c = CodecOf(root, v.GetProperty("config").GetString()!);
                var bytes = c.EncodeState(StateOf(v.GetProperty("state")));
                Assert.Equal(v.GetProperty("hex").GetString(), Hex(bytes));
                Assert.Equal(v.GetProperty("bits").GetInt32(), c.StateBits);
                Assert.True(c.DecodeState(Convert.FromHexString(v.GetProperty("hex").GetString()!), out var d), name);
                AssertState(StateOf(v.GetProperty("decoded")), d, name);
                n++;
            }
            _out.WriteLine("states: " + n + " cases passed");
            Assert.Equal(9, n);
        }

        [Fact]
        public void InputsEncodeAndDecodeBothWays()
        {
            var root = Load();
            var n = 0;
            foreach (var v in root.GetProperty("inputs").EnumerateArray())
            {
                var c = CodecOf(root, v.GetProperty("config").GetString()!);
                Assert.Equal(v.GetProperty("hex").GetString(), Hex(c.EncodeInput(InputOf(v.GetProperty("input")))));
                Assert.True(c.DecodeInput(Convert.FromHexString(v.GetProperty("hex").GetString()!), out var d));
                var want = InputOf(v.GetProperty("decoded"));
                Assert.True(Math.Abs(want.MoveX - d.MoveX) < 1e-5 && Math.Abs(want.MoveY - d.MoveY) < 1e-5 && Math.Abs(want.Yaw - d.Yaw) < 1e-5 && Math.Abs(want.Pitch - d.Pitch) < 1e-5);
                Assert.Equal(want.Buttons, d.Buttons);
                n++;
            }
            _out.WriteLine("inputs: " + n + " cases passed");
            Assert.Equal(4, n);
        }

        [Fact]
        public void EventArgumentsEncodeAndDecodeBothWays()
        {
            var root = Load();
            var n = 0;
            foreach (var v in root.GetProperty("args").EnumerateArray())
            {
                var c = CodecOf(root, v.GetProperty("config").GetString()!);
                var act = Action(v.GetProperty("event").GetString()!);
                Assert.Equal(v.GetProperty("id").GetInt32(), (int)act);
                Assert.Equal(v.GetProperty("hex").GetString(), Hex(c.EncodeArgs(act, ArgsOf(v.GetProperty("args")))));
                Assert.True(c.DecodeArgs(act, Convert.FromHexString(v.GetProperty("hex").GetString()!), out var d));
                var w = ArgsOf(v.GetProperty("decoded"));
                Assert.True(Math.Abs(w.Impact - d.Impact) < 1e-5 && Math.Abs(w.Yaw - d.Yaw) < 1e-5 && Math.Abs(w.Pitch - d.Pitch) < 1e-5 && Math.Abs(w.Power - d.Power) < 1e-5, v.GetProperty("name").GetString());
                Assert.True(w.View == d.View && w.Swing == d.Swing && w.Target == d.Target && w.Slot == d.Slot && w.By == d.By && w.Damage == d.Damage && w.Emote == d.Emote);
                n++;
            }
            _out.WriteLine("args: " + n + " cases passed");
            Assert.Equal(13, n);
        }

        [Fact]
        public void KindFiveMessagesEncodeAndDecodeBothWays()
        {
            var n = 0;
            foreach (var v in Load().GetProperty("events").EnumerateArray())
            {
                var evs = v.GetProperty("events").EnumerateArray().Select(e => new WireEvent(e.GetProperty("player").GetUInt32(), e.GetProperty("seq").GetUInt32(),
                    e.GetProperty("id").GetByte(), e.GetProperty("tick").GetUInt32(), Convert.FromHexString(e.GetProperty("argsHex").GetString()!))).ToList();
                var bytes = PlayerWire.EncodePlayerEvents(evs);
                Assert.Equal(v.GetProperty("hex").GetString(), Hex(bytes));
                var back = new List<WireEvent>();
                Assert.Null(PlayerWire.TryDecodePlayerEvents(Convert.FromHexString(v.GetProperty("hex").GetString()!), back));
                Assert.Equal(evs.Count, back.Count);
                for (var i = 0; i < evs.Count; i++)
                {
                    Assert.Equal(evs[i].Player, back[i].Player); Assert.Equal(evs[i].Seq, back[i].Seq); Assert.Equal(evs[i].Id, back[i].Id);
                    Assert.Equal(evs[i].Tick, back[i].Tick); Assert.Equal(evs[i].Args, back[i].Args);
                }
                n++;
            }
            _out.WriteLine("events: " + n + " cases passed");
            Assert.Equal(4, n);
        }

        [Fact]
        public void InvalidCasesFailWithTheirErrorName()
        {
            var root = Load();
            var n = 0;
            var covered = new HashSet<string>();
            foreach (var v in root.GetProperty("invalid").EnumerateArray())
            {
                var c = CodecOf(root, v.GetProperty("config").GetString()!);
                var bytes = Convert.FromHexString(v.GetProperty("hex").GetString()!);
                var kind = v.GetProperty("kind").GetString();
                var name = v.GetProperty("name").GetString();
                if (kind == "state") Assert.False(c.DecodeState(bytes, out _), name);
                else if (kind == "input") Assert.False(c.DecodeInput(bytes, out _), name);
                else if (kind == "args") Assert.False(c.DecodeArgs(Action(v.GetProperty("event").GetString()!), bytes, out _), name);
                else
                {
                    var err = PlayerWire.TryDecodePlayerEvents(bytes, new List<WireEvent>());
                    Assert.Equal(v.GetProperty("error").GetString(), err);
                    covered.Add(err!);
                }
                n++;
            }
            foreach (var e in new[] { "too_short", "trailing", "varint", "range", "count_0", "player_0", "seq_0", "event_id" }) Assert.Contains(e, covered);
            _out.WriteLine("invalid: " + n + " cases passed, kind 5 error names hit: " + string.Join(", ", covered.OrderBy(x => x)));
            Assert.Equal(18, n);
        }

        [Fact]
        public void LeftOutFieldsShortenTheState()
        {
            var full = new PlayerCodec();
            var lean = new PlayerCodec(new PlayerWireConfig(Omit: new[] { "velocity", "pitch", "aiming", "blocking", "team" }));
            Assert.Equal(16, full.StateBytes);
            Assert.True(lean.StateBytes < full.StateBytes);
            Assert.True(lean.DecodeState(lean.EncodeState(new PlayerState { X = 3, Vx = 9 }), out var s));
            Assert.Equal(0, s.Vx);
            Assert.Throws<ArgumentException>(() => new PlayerCodec(new PlayerWireConfig(Omit: new[] { "x" })));
            Assert.Throws<ArgumentException>(() => new PlayerCodec(new PlayerWireConfig(Omit: new[] { "teleport" })));
            Assert.Equal(12, new PlayerCodec(new PlayerWireConfig(Space: "2d")).StateBytes);
        }
    }
}
